            "parameters": {
                "type": "object",
                "properties": {
                    "query": {
                        "type": "string",
                        "description": "搜索关键词"
                    },
                    "max_results": {
                        "type": "integer",
                        "description": "最大返回数量",
                        "default": 5
                    }
                },
                "required": ["query"]
            }
        }
    }
]

# 用户提问
messages = [
    {"role": "user", "content": "查找关于社交媒体对青少年心理健康影响的中文研究"}
]

